'use strict';
const M=ForestModel,$=id=>document.getElementById(id),fmt=n=>Math.round(n).toLocaleString('en-US'),pct=n=>(100*n).toFixed(1)+'%',names=pair=>pair.map(i=>M.stands[i].id).join(' + ');
let experiment,testSeed=1000042;
function readConfig(){const p=Number($('risk').value)/100,n=Number($('sample').value),seed=$('seed').valueAsNumber;if(!Number.isInteger(seed)||seed<1||seed>999999){$('control-status').textContent='Enter a whole-number training seed from 1 to 999,999.';$('seed').setAttribute('aria-invalid','true');return null;}$('seed').removeAttribute('aria-invalid');return {p,n,seed};}
function run(){const config=readConfig();if(!config)return;const training=M.scenarios(config.n,config.p,config.seed),det=M.fit(training.slice(0,1)),saa=M.fit(training);experiment={config,training,det,saa};renderForest();renderPlans();test();$('control-status').textContent=`Showing seed ${config.seed}, ${config.n} training ${config.n===1?'future':'futures'}, and ${pct(config.p)} exposed-stand fire chance. Settings applied.`;}
function renderForest(){const {p}=experiment.config;$('stands').innerHTML=M.stands.map(s=>`<article class="stand ${s.risk===1?'exposed':''}"><span class="tree" aria-hidden="true">↟</span><strong>${s.id}</strong><small>${s.risk===1?'EXPOSED':'SHELTERED'}</small><p>Age <b>${s.age}</b> years<br>${fmt(M.volume(s.age))} m³ now<br><b>${pct(p*s.risk)}</b> fire / decade</p></article>`).join('');}
function renderPlans(){const {det,saa,config}=experiment;$('training-caption').textContent=`Training seed ${config.seed} · ${config.n} SAA futures · Same 15 choices`;$('plans').innerHTML=[[det,'det','Single-scenario model','Best for one sampled future',1],[saa,'saa','SAA model','Best average across the training sample',config.n]].map(([fit,cls,label,description,n])=>`<article class="plan ${cls}"><span class="label">${label}</span><h3>Harvest ${names(fit.plan)}</h3><div class="pair" aria-label="Selected stands">${fit.plan.map(i=>`<span>${M.stands[i].id}</span>`).join('')}</div><p>${description}.</p><div class="first"><strong>${fmt(fit.plan.reduce((s,i)=>s+M.volume(M.stands[i].age),0))} m³</strong> harvested in decade 1</div><p><b>${fmt(fit.score)} m³</b> ${n===1?'on its one training future':'average on its '+n+' training futures'} over 100 years.</p></article>`).join('');$('candidate-table').innerHTML=M.plans.map((plan,i)=>`<tr class="${names(plan)===names(saa.plan)?'picked':''}"><td>${names(plan)} ${names(plan)===names(det.plan)?'· Single':''} ${names(plan)===names(saa.plan)?'· SAA':''}</td><td>${fmt(det.scores[i])}</td><td>${fmt(saa.scores[i])}</td></tr>`).join('');}
function test(){experiment.paths=M.scenarios(1000,experiment.config.p,testSeed);experiment.results=M.compare(experiment.det.plan,experiment.saa.plan,experiment.paths,250000);$('future-index').value=1;renderResults();renderFuture();}
function renderResults(){const r=experiment.results,same=names(experiment.det.plan)===names(experiment.saa.plan),positive=r.gain>0;$('test-caption').textContent=`Test seed ${testSeed} · 1,000 independent holdout draws · ${pct(experiment.config.p)} exposed fire chance · Plans remain frozen during testing.`;let headline,explanation;if(same){headline='Same first harvest. Same outcomes.';explanation='Both methods selected the same pair. With identical fires and identical later rules, their entire harvest trajectories match.';}else if(r.gain===0){headline='The sample means are tied.';explanation='The two first harvests produce the same mean on this test sample. Individual outcomes can still differ.';}else {headline=`${positive?'SAA':'Single scenario'} leads by ${fmt(Math.abs(r.gain))} m³ on average.`;explanation=`That is ${((Math.abs(r.gain)/r.det.mean)*100).toFixed(2)}% of the single-scenario mean. ${r.ci[0]>0?'The paired 95% interval is above zero, supporting an SAA advantage under this teaching model.':r.ci[1]<0?'The paired 95% interval is below zero, favoring the single-scenario choice in this run.':'The paired 95% interval includes zero; this test does not clearly separate their expected harvests.'}`;}$('verdict').innerHTML=`<strong>${headline}</strong><p>${explanation}</p>`;
const metrics=[['Mean harvest','Primary objective: larger is better','mean',v=>fmt(v)+' m³'],['Poor-outcome harvest','10th percentile: about 10% of outcomes are this low or lower','p10',v=>fmt(v)+' m³'],['Meet 250,000 m³ target','100-year target, not a per-decade constraint','success',pct]];$('results').innerHTML=metrics.map(([title,description,key,format])=>`<tr><td>${title}<small>${description}</small></td><td class="${r.det[key]>r.saa[key]?'best':''}">${format(r.det[key])}</td><td class="${r.saa[key]>r.det[key]?'best':''}">${format(r.saa[key])}</td></tr>`).join('');$('interval').textContent=`SAA − single scenario: ${r.gain>=0?'+':''}${fmt(r.gain)} m³. Approximate 95% interval: [${fmt(r.ci[0])}, ${fmt(r.ci[1])}] m³.`;
const losses=Math.max(0,1-r.wins-r.ties);$('win-bar').innerHTML=`<span style="width:${r.wins*100}%;background:#2c7159" title="SAA wins"></span><span style="width:${r.ties*100}%;background:#c5cdbb" title="Ties"></span><span style="width:${losses*100}%;background:#b67b38" title="Single scenario wins"></span>`;$('win-bar').setAttribute('aria-label',`SAA wins ${pct(r.wins)}; ties ${pct(r.ties)}; single scenario wins ${pct(losses)}`);$('win-text').textContent=`SAA wins ${pct(r.wins)} · Ties ${pct(r.ties)} · Single scenario wins ${pct(losses)}`;drawHistogram(r.diff);}
function drawHistogram(diff){const max=Math.max(4000,...diff.map(Math.abs)),width=Math.ceil(max/10/4000)*4000,bins=Array(21).fill(0);diff.forEach(d=>bins[10+(d===0?0:Math.sign(d)*Math.ceil(Math.abs(d)/width))]++);const top=Math.max(...bins,1),left=65,bottom=211,bw=39,gap=3;let svg=`<title>Paired differences over 1,000 test futures</title><desc>Negative differences favor the single-scenario plan; positive differences favor SAA. The center bar counts exact ties.</desc><text x="18" y="19" font-size="12" fill="#61736a">Futures</text>`;for(let j=0;j<=4;j++){let y=bottom-170*j/4;svg+=`<line x1="60" y1="${y}" x2="953" y2="${y}" stroke="#e0e5da"/><text x="50" y="${y+4}" text-anchor="end" font-size="11" fill="#61736a">${Math.round(top*j/4)}</text>`;}bins.forEach((n,i)=>{const x=left+i*(bw+gap),h=n/top*170;const lo=(i-10)*width,hi=(i<10?lo+width:lo);const label=i===10?'Exact tie':i<10?`${fmt(lo)} to below ${fmt(hi)} m³`:`above ${fmt(lo-width)} to ${fmt(lo)} m³`;svg+=`<rect x="${x}" y="${bottom-h}" width="${bw}" height="${h}" rx="2" fill="${i<10?'#b67b38':i>10?'#2c7159':'#becbb6'}"><title>${label}: ${n} futures</title></rect>`;});svg+=`<text x="65" y="237" font-size="12" fill="#916025">← Single-scenario advantage</text><text x="504" y="237" text-anchor="middle" font-size="12" fill="#61736a">0 (ties)</text><text x="942" y="237" text-anchor="end" font-size="12" fill="#2c7159">SAA advantage →</text><text x="504" y="262" text-anchor="middle" font-size="12" fill="#61736a">Difference in 100-year harvest (m³) · nonzero bins ${fmt(width)} m³ wide</text>`;$('histogram').innerHTML=svg;$('hist-summary').textContent=`Observed paired differences range from ${fmt(Math.min(...diff))} to ${fmt(Math.max(...diff))} m³. Exact ties: ${diff.filter(d=>d===0).length} of 1,000 futures.`;}
function selectedFuture(){const n=$('future-index').valueAsNumber;if(!Number.isInteger(n)||n<1||n>1000){$('future-index').setAttribute('aria-invalid','true');$('future-result').textContent='Enter a whole-number future from 1 to 1,000. The timeline below retains the last valid selection.';return null;}$('future-index').removeAttribute('aria-invalid');return n-1;}
function renderFuture(){const i=selectedFuture();if(i===null)return;const path=experiment.paths[i],a=M.simulate(experiment.det.plan,path,true),b=M.simulate(experiment.saa.plan,path,true),t=Number($('decade').value)-1;const d=b.total-a.total;$('future-result').textContent=`Future ${i+1}: ${d===0?'tie':d>0?'SAA ahead by '+fmt(d)+' m³':'single scenario ahead by '+fmt(-d)+' m³'}.`;$('timeline-head').innerHTML=`<tr><th>100-year horizon</th>${Array.from({length:10},(_,j)=>`<th class="${j===t?'selected':''}">D${j+1}<small>Years ${j*10}–${(j+1)*10}</small></th>`).join('')}</tr>`;const row=(label,values,cls)=>`<tr class="${cls}"><td>${label}</td>${values.map((v,j)=>`<td class="${j===t?'selected':''}">${v}</td>`).join('')}</tr>`;$('timeline-body').innerHTML=row('Shared fires ✦',path.map(f=>f.map((fire,j)=>fire?M.stands[j].id:'').filter(Boolean).join(', ')||'None'),'fire')+row('Single: stands',a.decades.map(d=>d.cut.map(j=>M.stands[j].id).join(', ')||'None'),'det-row')+row('Single: m³',a.decades.map(d=>fmt(d.harvest)),'det-row')+row('SAA: stands',b.decades.map(d=>d.cut.map(j=>M.stands[j].id).join(', ')||'None'),'saa-row')+row('SAA: m³',b.decades.map(d=>fmt(d.harvest)),'saa-row');$('decade-label').textContent=`${t+1} · years ${t*10}–${(t+1)*10}`;const fires=path[t].map((f,j)=>f?M.stands[j].id:'').filter(Boolean).join(', ')||'none';$('decade-detail').innerHTML=[[a,'Single-scenario plan'],[b,'SAA plan']].map(([trace,title])=>{const d=trace.decades[t];return `<article><h3>${title} / decade ${t+1}</h3><p>Start ages: ${d.before.map((age,j)=>`${M.stands[j].id} ${age}`).join(' · ')} years.</p><p><strong>Harvest ${d.cut.length?d.cut.map(j=>M.stands[j].id).join(' + '):'none'}: ${fmt(d.harvest)} m³.</strong><br>Then fires affect: ${fires}.<br>Cumulative harvest: ${fmt(d.total)} m³.</p><p class="caption">${t===0?'The first pair was chosen before this test future was seen.':'This choice uses only current stand ages, after previous fires and growth.'}</p></article>`;}).join('');}
function csv(){const r=experiment.results,c=experiment.config;const lines=['test_future,training_seed,training_scenarios,test_seed,exposed_fire_probability,first_pair_single,first_pair_saa,single_harvest_m3,saa_harvest_m3,difference_m3',...r.a.map((v,i)=>[i+1,c.seed,c.n,testSeed,c.p,names(experiment.det.plan),names(experiment.saa.plan),v,r.b[i],r.diff[i]].join(','))];const url=URL.createObjectURL(new Blob([lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='forest-decision-paired-test.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('run').addEventListener('click',run);for(const id of ['risk','sample','seed'])$(id).addEventListener('input',()=>{$('risk-label').textContent=$('risk').value+'%';$('control-status').textContent='Settings changed. Select “Build & compare” to apply them; displayed results still describe the previous experiment.';});$('new-test').addEventListener('click',()=>{testSeed+=1009;test();});$('future-index').addEventListener('input',renderFuture);$('next-future').addEventListener('click',()=>{const i=selectedFuture();if(i===null)return;$('future-index').value=(i+1)%1000+1;renderFuture();});$('decade').addEventListener('input',renderFuture);$('download').addEventListener('click',csv);$('check').addEventListener('click',()=>{const choice=document.querySelector('input[name="quiz"]:checked'),feedback=$('quiz-feedback');feedback.className=choice?.value==='1'?'good':'bad';feedback.textContent=!choice?'Choose an answer first.':choice.value==='1'?'Exactly. Shared holdout futures compare decisions fairly. The mean matches our objective, and the interval shows test-sampling uncertainty.':'Try again. A plan can look best on its training sample or one lucky future. Evaluate both on the same new futures and report the uncertainty.';});$('reset').addEventListener('click',()=>{$('risk').value=25;$('risk-label').textContent='25%';$('sample').value=100;$('seed').value=42;$('decade').value=1;testSeed=1000042;run();});run();
